// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: caller address and initial ether
        address alice = address(0x1234);
        vm.deal(alice, 20 ether);

        // Step 1: Initialize the contract
        vm.prank(alice);
        c.Initialized();

        // Step 2: Set MinSum to 5 ether
        vm.prank(alice);
        c.SetMinSum(5 ether);

        // Step 3: Deposit 10 ether from alice
        vm.prank(alice);
        c.Deposit{value: 10 ether}();

        // Step 4: Collect 5 ether – the critical call
        vm.prank(alice);
        c.Collect(5 ether);

        // Assert: reference would have balance = 10 - 5 = 5 ether;
        // bug adds: balance = 10 + 5 = 15 ether; so we check that
        // the balance is NOT equal to the reference value (5 ether).
        // Since bug returns 15, assertTrue(c.balances(alice) != 5 ether) fails for bug.
        // But we want test to pass on reference (balance == 5) and fail on bug (balance == 15).
        // So assert that balances[alice] == 5 ether – reference passes, bug fails.
        assertTrue(c.balances(alice) == 5 ether, "Reference: balance should be 5 after Collect(5)");
    }
}

