    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Deposit{value: 1 ether}();
        // set MinSum to 0 so condition balances >= 0 and balances >= _am always true for any positive _am
        c.SetMinSum(0);
        c.Initialized();
        vm.prank(user);
        c.Collect(1 ether);
        uint balAfter = c.balances(user);
        // on reference: 1 ether - 1 ether = 0
        // on bug: 1 ether + 1 ether = 2 ether
        assertTrue(balAfter == 0 ether, "Reference: balance after Collect should be 0");
    }
}

