        c.Initialized();

        address alice = address(0x1234);
        vm.deal(alice, 3 ether);
        vm.prank(alice);
        c.Deposit{value: 3 ether}();

        // Call Collect — reference reverts, bug succeeds
        vm.prank(alice);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, 3 ether));
        // After call, in reference, success == false (revert) and balance unchanged.
