pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize the contract
        c.SetMinSum(5 ether);
        c.Initialized();

        // Use two accounts: alice deposits 10 ether, bob deposits 5 ether
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 10 ether);
        vm.deal(bob, 5 ether);

        vm.prank(alice);
        c.Deposit{value: 10 ether}();
        vm.prank(bob);
        c.Deposit{value: 5 ether}();

        // Alice tries to collect 10 ether but only has 10 ether (balance >= MinSum and balance >= _am): should succeed
        vm.prank(alice);
        c.Collect(10 ether);

        // Bob tries to collect 10 ether but only has 5 ether (balance >= MinSum but balance < _am)
        bool ok;
        address target = bob;
        vm.prank(target);
        try c.Collect(10 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference, this call reverts (ok == false); in the buggy version, it succeeds (ok == true)
        // Here we assert the reference behavior: the call should revert
        assertTrue(!ok, "Collect should revert when balance < _am");
    }
}

